INSERT INTO `preguntas` VALUES (1,1,1,'multiple','¿Cuál es la función principal de la CPU?','[\"Almacenar datos permanentemente\", \"Procesar instrucciones y ejecutar programas\", \"Conectar dispositivos externos\", \"Mostrar imágenes en pantalla\"]','Procesar instrucciones y ejecutar programas','La CPU (Unidad Central de Procesamiento) es el cerebro del computador, encargada de procesar instrucciones.','facil',10,1,'2026-05-28 19:54:03'),(2,1,1,'multiple','¿Qué tipo de memoria pierde su contenido al apagar el computador?','[\"ROM\", \"Disco duro\", \"RAM\", \"SSD\"]','RAM','La RAM (Memoria de Acceso Aleatorio) es volátil, pierde su información cuando se apaga el equipo.','facil',10,1,'2026-05-28 19:54:03'),(3,1,1,'verdadero_falso','¿El disco duro SSD es más rápido que el disco duro HDD?','[\"Verdadero\", \"Falso\"]','Verdadero','Los SSD usan memoria flash y no tienen partes móviles, lo que los hace significativamente más rápidos.','facil',10,1,'2026-05-28 19:54:03'),(4,1,1,'multiple','¿Qué significa GPU?','[\"General Processing Unit\", \"Graphics Processing Unit\", \"Global Power Unit\", \"Graphics Power Upgrade\"]','Graphics Processing Unit','GPU es la Unidad de Procesamiento Gráfico, encargada de renderizar imágenes y video.','medio',10,1,'2026-05-28 19:54:03'),(5,1,1,'multiple','¿Cuál es la unidad básica de almacenamiento digital?','[\"Byte\", \"Kilobyte\", \"Bit\", \"Megabyte\"]','Bit','El bit es la unidad mínima de información digital, puede ser 0 o 1.','facil',10,1,'2026-05-28 19:54:03'),(6,1,1,'multiple','¿Qué dispositivo convierte la energía eléctrica para alimentar los componentes del PC?','[\"Motherboard\", \"Fuente de poder\", \"Tarjeta de red\", \"Procesador\"]','Fuente de poder','La fuente de poder convierte la corriente alterna (AC) en corriente directa (DC) para los componentes.','facil',10,1,'2026-05-28 19:54:03'),(7,1,1,'verdadero_falso','¿La placa madre (motherboard) conecta todos los componentes del computador?','[\"Verdadero\", \"Falso\"]','Verdadero','La placa madre es el circuito principal que interconecta CPU, RAM, almacenamiento y demás componentes.','facil',10,1,'2026-05-28 19:54:03'),(8,1,1,'multiple','¿Cuántos bits tiene un byte?','[\"4\", \"16\", \"8\", \"32\"]','8','Un byte está compuesto por 8 bits, es la unidad estándar de almacenamiento.','facil',10,1,'2026-05-28 19:54:03'),(9,1,1,'multiple','¿Qué es el caché de la CPU?','[\"Un tipo de disco duro\", \"Memoria ultrarrápida dentro del procesador\", \"Un programa antivirus\", \"Una tarjeta gráfica integrada\"]','Memoria ultrarrápida dentro del procesador','El caché es una memoria de alta velocidad integrada en la CPU para acelerar el acceso a datos frecuentes.','medio',10,1,'2026-05-28 19:54:03'),(10,1,1,'multiple','¿Qué significa HDD?','[\"Hard Disk Drive\", \"High Definition Display\", \"Hardware Digital Device\", \"High Data Drive\"]','Hard Disk Drive','HDD (Hard Disk Drive) es el disco duro tradicional con platos magnéticos giratorios.','facil',10,1,'2026-05-28 19:54:03'),(11,1,2,'multiple','¿Cuál de estos es un sistema operativo?','[\"Microsoft Word\", \"Linux\", \"Google Chrome\", \"Photoshop\"]','Linux','Linux es un sistema operativo de código abierto ampliamente usado en servidores y computadoras personales.','facil',10,1,'2026-05-28 19:54:03'),(12,1,2,'verdadero_falso','¿Windows es un sistema operativo de código abierto?','[\"Verdadero\", \"Falso\"]','Falso','Windows es un sistema operativo propietario de Microsoft, no es de código abierto.','facil',10,1,'2026-05-28 19:54:03'),(13,1,2,'multiple','¿Qué es el kernel de un sistema operativo?','[\"La interfaz gráfica del usuario\", \"El núcleo que gestiona recursos del hardware\", \"Un programa de ofimática\", \"El explorador de archivos\"]','El núcleo que gestiona recursos del hardware','El kernel es el núcleo del SO, gestiona memoria, procesos y comunicación con el hardware.','medio',10,1,'2026-05-28 19:54:03'),(14,1,2,'multiple','¿Cuál es el sistema operativo más usado en smartphones Android?','[\"Windows Mobile\", \"iOS\", \"Linux (Android)\", \"macOS\"]','Linux (Android)','Android está basado en el kernel de Linux, adaptado para dispositivos móviles.','medio',10,1,'2026-05-28 19:54:03'),(15,1,2,'multiple','¿Qué significa GUI?','[\"General User Interface\", \"Graphical User Interface\", \"Global Unified Interface\", \"Graphics Upgrade Installation\"]','Graphical User Interface','GUI es la Interfaz Gráfica de Usuario, permite interactuar con el sistema mediante íconos y ventanas.','facil',10,1,'2026-05-28 19:54:03'),(16,2,4,'multiple','¿Qué significa LAN?','[\"Large Area Network\", \"Local Area Network\", \"Linked Access Node\", \"Low Amplitude Network\"]','Local Area Network','LAN es una red de área local que conecta dispositivos en un área geográfica pequeña como una oficina.','facil',10,1,'2026-05-28 19:54:03'),(17,2,4,'verdadero_falso','¿Una WAN cubre un área geográfica más grande que una LAN?','[\"Verdadero\", \"Falso\"]','Verdadero','WAN (Wide Area Network) puede cubrir países o continentes, mientras que LAN es local.','facil',10,1,'2026-05-28 19:54:03'),(18,2,4,'multiple','¿Qué dispositivo conecta múltiples redes diferentes entre sí?','[\"Switch\", \"Hub\", \"Router\", \"Módem\"]','Router','El router dirige el tráfico entre redes diferentes, como tu red local e internet.','facil',10,1,'2026-05-28 19:54:03'),(19,2,4,'multiple','¿Qué es una dirección IP?','[\"El nombre de una red WiFi\", \"Un identificador único de un dispositivo en la red\", \"La velocidad de conexión a internet\", \"El tipo de cable de red\"]','Un identificador único de un dispositivo en la red','La dirección IP identifica de forma única a cada dispositivo conectado en una red.','facil',10,1,'2026-05-28 19:54:03'),(20,2,4,'multiple','¿Cuántos bits tiene una dirección IPv4?','[\"16\", \"64\", \"128\", \"32\"]','32','IPv4 usa 32 bits, representados como 4 grupos de números (ej: 192.168.1.1).','medio',10,1,'2026-05-28 19:54:03'),(21,2,4,'multiple','¿Qué hace un switch en una red?','[\"Conecta la red a internet\", \"Amplifica la señal WiFi\", \"Conecta dispositivos dentro de la misma red local\", \"Asigna direcciones IP\"]','Conecta dispositivos dentro de la misma red local','El switch conecta múltiples dispositivos en una LAN y dirige el tráfico de forma eficiente.','medio',10,1,'2026-05-28 19:54:03'),(22,2,4,'verdadero_falso','¿El WiFi usa ondas de radio para transmitir datos?','[\"Verdadero\", \"Falso\"]','Verdadero','WiFi transmite datos usando ondas de radio en las frecuencias de 2.4 GHz y 5 GHz.','facil',10,1,'2026-05-28 19:54:03'),(23,2,4,'multiple','¿Qué significa DNS?','[\"Data Network System\", \"Domain Name System\", \"Digital Network Service\", \"Dynamic Node Setup\"]','Domain Name System','DNS traduce nombres de dominio (como google.com) a direcciones IP.','medio',10,1,'2026-05-28 19:54:03'),(24,2,5,'multiple','¿Qué protocolo se usa para navegar páginas web de forma segura?','[\"HTTP\", \"FTP\", \"HTTPS\", \"SMTP\"]','HTTPS','HTTPS (HTTP Secure) encripta la comunicación entre el navegador y el servidor web.','facil',10,1,'2026-05-28 19:54:03'),(25,2,5,'multiple','¿Qué protocolo se usa para enviar correos electrónicos?','[\"HTTP\", \"FTP\", \"DNS\", \"SMTP\"]','SMTP','SMTP (Simple Mail Transfer Protocol) es el protocolo estándar para el envío de correos.','medio',10,1,'2026-05-28 19:54:03'),(26,2,5,'verdadero_falso','¿TCP garantiza la entrega de los datos?','[\"Verdadero\", \"Falso\"]','Verdadero','TCP (Transmission Control Protocol) verifica que los datos lleguen completos y en orden.','medio',10,1,'2026-05-28 19:54:03'),(27,2,5,'multiple','¿En qué capa del modelo OSI opera el protocolo IP?','[\"Capa de aplicación\", \"Capa de transporte\", \"Capa de red\", \"Capa de enlace\"]','Capa de red','IP opera en la capa 3 (red) del modelo OSI, encargada del direccionamiento y enrutamiento.','dificil',10,1,'2026-05-28 19:54:03'),(28,2,5,'multiple','¿Qué puerto usa el protocolo HTTP por defecto?','[\"443\", \"21\", \"80\", \"22\"]','80','HTTP usa el puerto 80 por defecto, mientras que HTTPS usa el 443.','medio',10,1,'2026-05-28 19:54:03'),(29,3,7,'multiple','¿Qué es un algoritmo?','[\"Un lenguaje de programación\", \"Una secuencia de pasos para resolver un problema\", \"Un tipo de base de datos\", \"Un componente de hardware\"]','Una secuencia de pasos para resolver un problema','Un algoritmo es un conjunto finito de instrucciones ordenadas para resolver un problema.','facil',10,1,'2026-05-28 19:54:03'),(30,3,7,'multiple','¿Cuál de estos es un lenguaje de programación?','[\"HTML\", \"CSS\", \"Python\", \"Markdown\"]','Python','Python es un lenguaje de programación de propósito general, ampliamente usado en ciencia de datos e IA.','facil',10,1,'2026-05-28 19:54:03'),(31,3,7,'verdadero_falso','¿HTML es un lenguaje de programación?','[\"Verdadero\", \"Falso\"]','Falso','HTML es un lenguaje de marcado para estructurar páginas web, no un lenguaje de programación.','medio',10,1,'2026-05-28 19:54:03'),(32,3,7,'multiple','¿Qué es una variable en programación?','[\"Un error en el código\", \"Un espacio en memoria para almacenar datos\", \"Un tipo de bucle\", \"Una función matemática\"]','Un espacio en memoria para almacenar datos','Una variable es un contenedor con nombre que almacena un valor que puede cambiar durante la ejecución.','facil',10,1,'2026-05-28 19:54:03'),(33,3,7,'multiple','¿Qué es la compilación de un programa?','[\"Ejecutar el programa\", \"Traducir el código fuente a lenguaje máquina\", \"Depurar errores\", \"Guardar el archivo\"]','Traducir el código fuente a lenguaje máquina','Un compilador traduce el código escrito por el programador al lenguaje que entiende la máquina.','medio',10,1,'2026-05-28 19:54:03'),(34,3,7,'multiple','¿Qué estructura de datos almacena elementos en orden LIFO?','[\"Cola\", \"Árbol\", \"Pila (Stack)\", \"Lista enlazada\"]','Pila (Stack)','LIFO (Last In, First Out): el último elemento en entrar es el primero en salir. Es una pila.','medio',10,1,'2026-05-28 19:54:03'),(35,3,7,'verdadero_falso','¿Un bucle infinito es siempre un error de programación?','[\"Verdadero\", \"Falso\"]','Falso','Los bucles infinitos se usan intencionalmente en servidores y sistemas embebidos que deben correr continuamente.','dificil',10,1,'2026-05-28 19:54:03'),(36,3,7,'multiple','¿Qué operador lógico devuelve verdadero solo si ambas condiciones son verdaderas?','[\"OR\", \"NOT\", \"AND\", \"XOR\"]','AND','El operador AND (Y) devuelve verdadero únicamente cuando todas las condiciones son verdaderas.','facil',10,1,'2026-05-28 19:54:03'),(37,4,11,'multiple','¿Qué significa SQL?','[\"Structured Query Language\", \"Simple Query Logic\", \"System Query Language\", \"Stored Query List\"]','Structured Query Language','SQL es el lenguaje estándar para gestionar y consultar bases de datos relacionales.','facil',10,1,'2026-05-28 19:54:03'),(38,4,11,'multiple','¿Qué comando SQL se usa para obtener datos de una tabla?','[\"INSERT\", \"UPDATE\", \"SELECT\", \"DELETE\"]','SELECT','SELECT es el comando para consultar y recuperar datos de una o más tablas.','facil',10,1,'2026-05-28 19:54:03'),(39,4,11,'verdadero_falso','¿Una clave primaria puede tener valores repetidos?','[\"Verdadero\", \"Falso\"]','Falso','La clave primaria (PRIMARY KEY) identifica de forma única cada registro, no admite duplicados.','facil',10,1,'2026-05-28 19:54:03'),(40,4,11,'multiple','¿Qué comando elimina todos los registros de una tabla?','[\"DROP TABLE\", \"DELETE FROM tabla\", \"REMOVE ALL\", \"CLEAR TABLE\"]','DELETE FROM tabla','DELETE FROM tabla elimina los registros. DROP TABLE eliminaría también la estructura de la tabla.','medio',10,1,'2026-05-28 19:54:03'),(41,4,11,'multiple','¿Qué es una clave foránea (FOREIGN KEY)?','[\"Un índice para búsqueda rápida\", \"Un campo que referencia la clave primaria de otra tabla\", \"Una restricción de unicidad\", \"Un tipo de dato especial\"]','Un campo que referencia la clave primaria de otra tabla','La clave foránea establece relaciones entre tablas, apuntando a la clave primaria de otra tabla.','medio',10,1,'2026-05-28 19:54:03'),(42,4,11,'multiple','¿Qué cláusula SQL filtra resultados según una condición?','[\"ORDER BY\", \"GROUP BY\", \"WHERE\", \"HAVING\"]','WHERE','WHERE filtra las filas que cumplen una condición específica en la consulta.','facil',10,1,'2026-05-28 19:54:03'),(43,4,11,'verdadero_falso','¿MySQL es un sistema gestor de bases de datos relacional?','[\"Verdadero\", \"Falso\"]','Verdadero','MySQL es uno de los SGBD relacionales más populares del mundo, usa SQL como lenguaje.','facil',10,1,'2026-05-28 19:54:03'),(44,4,11,'multiple','¿Qué función SQL cuenta el número de registros?','[\"SUM()\", \"AVG()\", \"COUNT()\", \"MAX()\"]','COUNT()','COUNT() devuelve el número de filas que cumplen la condición especificada.','facil',10,1,'2026-05-28 19:54:03'),(45,5,13,'multiple','¿Qué es el phishing?','[\"Un tipo de virus\", \"Un ataque para robar información mediante engaños\", \"Un método de encriptación\", \"Un protocolo de red seguro\"]','Un ataque para robar información mediante engaños','El phishing engaña al usuario para que revele datos sensibles mediante correos o sitios falsos.','facil',10,1,'2026-05-28 19:54:03'),(46,5,13,'verdadero_falso','¿Un antivirus protege contra todos los tipos de malware?','[\"Verdadero\", \"Falso\"]','Falso','Los antivirus son útiles pero no garantizan protección total. Se necesitan múltiples capas de seguridad.','medio',10,1,'2026-05-28 19:54:03'),(47,5,13,'multiple','¿Qué es el ransomware?','[\"Software que muestra publicidad\", \"Malware que cifra archivos y pide rescate\", \"Un tipo de firewall\", \"Un protocolo de seguridad\"]','Malware que cifra archivos y pide rescate','El ransomware encripta los archivos de la víctima y exige un pago para recuperarlos.','medio',10,1,'2026-05-28 19:54:03'),(48,5,13,'multiple','¿Qué es un firewall?','[\"Un programa para editar imágenes\", \"Un sistema que filtra el tráfico de red\", \"Un tipo de virus\", \"Un dispositivo de almacenamiento\"]','Un sistema que filtra el tráfico de red','Un firewall monitorea y controla el tráfico de red según reglas de seguridad.','facil',10,1,'2026-05-28 19:54:03'),(49,5,13,'multiple','¿Cuál es una buena práctica para crear contraseñas seguras?','[\"Usar tu fecha de nacimiento\", \"Usar la misma contraseña en todos lados\", \"Combinar letras, números y símbolos\", \"Usar tu nombre completo\"]','Combinar letras, números y símbolos','Las contraseñas seguras combinan mayúsculas, minúsculas, números y símbolos especiales.','facil',10,1,'2026-05-28 19:54:03'),(50,5,13,'verdadero_falso','¿HTTPS garantiza que el sitio web es legítimo y confiable?','[\"Verdadero\", \"Falso\"]','Falso','HTTPS solo garantiza que la conexión está cifrada, no que el sitio sea legítimo.','dificil',10,1,'2026-05-28 19:54:03'),(51,5,13,'multiple','¿Qué es la ingeniería social en ciberseguridad?','[\"Programar robots\", \"Manipular personas para obtener información confidencial\", \"Diseñar redes\", \"Crear contraseñas seguras\"]','Manipular personas para obtener información confidencial','La ingeniería social explota la confianza humana para obtener acceso a sistemas o datos.','medio',10,1,'2026-05-28 19:54:03'),(52,5,13,'multiple','¿Qué significa 2FA?','[\"Two Factor Authentication\", \"Two File Access\", \"Transfer File Authorization\", \"Two Firewall Access\"]','Two Factor Authentication','2FA agrega una segunda capa de seguridad al inicio de sesión, además de la contraseña.','facil',10,1,'2026-05-28 19:54:03');
